import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-10-15 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-10-15 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-10-15T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","Crimson Project","Performance Optimization","Error Handling","Object Storage","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-15_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-10-15_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-10-15_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function n(s,i,a,_,p,g){return e(),r("div",null,[...i[0]||(i[0]=[o('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年10月15日</p><p><strong>参会人员</strong>： Mitch, Radek, Dan, Josh, 以及其他相关人员</p><p><strong>会议主题</strong>： Ceph crimson 项目进展、性能测试、错误处理优化、对象上下文工作、异步测试等</p><p><strong>关键细节与讨论议题</strong>：</p><p><strong>1. Crimson 项目进展</strong></p><ul><li>Mitch 汇报了 crimson 项目的进展，提到 Crimson 在性能上优于传统 OSD，特别是在多客户端场景下的高并发情况下。</li><li>讨论了使用多线程和优化锁机制来提升 Crimson 的性能。</li><li>实验表明，当 TP Strata 端口数为 2 时，Crimson 的性能优于 Safestore 默认选项。</li></ul><p><strong>2. 错误处理优化</strong></p><ul><li>讨论了使用 futures 和编译器特性进行错误处理的优缺点，并决定进行实验来比较不同方法的性能。</li><li>认为使用 futures 可能会带来不必要的性能开销，并决定尝试使用手动处理错误的方法。</li></ul><p><strong>3. 对象上下文工作</strong></p><ul><li>Radek 汇报了 crimson 对象上下文工作的进展，介绍了 intrusive LRU 和 snap context 的实现。</li><li>讨论了对象上下文工作对性能的影响，并决定进一步优化。</li></ul><p><strong>4. 异步测试</strong></p><ul><li>Dan 汇报了异步测试的进展，介绍了测试策略和测试结果。</li><li>讨论了异步测试中的问题，并决定进一步调查。</li></ul><p><strong>5. 其他</strong></p><ul><li>讨论了 crimson 中的 TOF 消息处理，并决定进行改进。</li><li>讨论了 crimson 的内存压缩和加密问题。</li></ul><p><strong>决定事项</strong>：</p><ul><li>进一步优化 crimson 的性能，包括使用多线程、优化锁机制和减少复制操作。</li><li>对错误处理进行实验，比较不同方法的性能。</li><li>完成对象上下文工作，并进一步优化。</li><li>完成异步测试，并解决测试中的问题。</li><li>改进 crimson 中的 TOF 消息处理。</li><li>调查 crimson 的内存压缩和加密问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Mitch 继续进行 crimson 的性能优化。</li><li>Radek 完成对象上下文工作，并进行优化。</li><li>Dan 完成异步测试，并解决测试中的问题。</li><li>其他相关人员继续进行相关工作。</li></ul><p>在原始字幕中，有部分内容可能存在误解或遗漏，例如对 Crimson 项目性能优化细节的描述不够具体。改进后的总结中，对关键细节进行了更准确的反映，并保留了相关的 Ceph 和计算机科学领域的英文关键词。</p>',20)])])}const u=t(l,[["render",n]]);export{c as __pageData,u as default};
